package app.lensly.app.export

/**
 * The frames of the AirVault pairing that Lensly exports for one labelled wallet: an Ethereum account and two Bitcoin accounts, each with a
 * name, a label and a group. WalletStoreBitcoinTest records them from Lensly, and Lumio's pairing test reads the same frames, so the two
 * apps agree on what a pairing carries. Re-record them only when the pairing itself changes.
 *
 * [FRAMES] is the version-2 code with the body stored as it is, which the JVM tests write. [V1_FRAMES] is the version-1 code that earlier
 * builds wrote for the same wallet, which Lumio still reads.
 */
object LabelledPairingGolden {
    val FRAMES: List<String> = listOf(
        "UR:AIRVAULT-PAIRING/1-",
        "UR:AIRVAULT-PAIRING/2-",
        "UR:AIRVAULT-PAIRING/3-",
        "UR:AIRVAULT-PAIRING/4-",
        "UR:AIRVAULT-PAIRING/5-",
        "UR:AIRVAULT-PAIRING/6-",
    )

    val V1_FRAMES: List<String> = listOf(
        "UR:AIRVAULT-PAIRING/1-",
        "UR:AIRVAULT-PAIRING/2-",
        "UR:AIRVAULT-PAIRING/3-",
        "UR:AIRVAULT-PAIRING/4-",
        "UR:AIRVAULT-PAIRING/5-",
        "UR:AIRVAULT-PAIRING/6-",
    )
}
